1	// Shared-hosting order pricing — a plain module (no "use server") so it can be
2	// imported both by lib/actions-hosting.ts (the wallet/card order path) and by
3	// lib/actions-payment-providers.ts (the PayPal/Coinbase order path) WITHOUT
4	// either of them re-deriving the formula, and without turning a pure pricing
5	// helper into a network-callable Server Action export for no reason — see
6	// test/auth-lockouts.test.ts's "HAZARD" suite, which exists precisely to catch
7	// exactly that mistake.
8	
9	import { annualDiscountPct } from "./annual-discount";
10	import { extraDiskPerGbCents } from "./disk-expand";
11	import { extraDiskCentsAt } from "./extra-disk";
12	import { termPriceCents } from "./billing-terms";
13	import { firstMonthCreditCents } from "./promo-redemption";
14	
15	/**
16	 * The money math for a hosting order, in ONE place so the card-split pre-check
17	 * (`placeHostingOrder`, lib/actions-hosting.ts), the authoritative debit
18	 * (`orderHostingAccountFor`) and the PayPal/Coinbase order-creation actions
19	 * (lib/actions-payment-providers.ts) can never diverge on a formula.
20	 * `fullCharge` is the true total (plan term + storage add-on); `promoCharge` is
21	 * what a granted first-month-free reduces it to (one PLAN month credited, the
22	 * add-on never). All the underlying helpers are pure, so call sites only ever
23	 * differ by the DB reads (annual %, per-GB rate, eligibility) they must each
24	 * make against the same instant.
25	 */
26	export async function hostingChargeCents(
27	  plan: { priceCents: number },
28	  term: number,
29	  extraGB: number,
30	): Promise<{ annualPct: number; planTermCents: number; extraTermCents: number; fullCharge: number; promoCharge: number }> {
31	  const annualPct = await annualDiscountPct();
32	  const perGbCents = await extraDiskPerGbCents();
33	  const extraTermCents = extraDiskCentsAt(extraGB, perGbCents) * term;
34	  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
35	  const fullCharge = planTermCents + extraTermCents;
36	  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
37	  return { annualPct, planTermCents, extraTermCents, fullCharge, promoCharge };
38	}
