8	import { annualDiscountPct } from "./annual-discount";
9	import { termPriceCents } from "./billing-terms";
10	import { emailMonthlyBaseCents } from "./product-billing";
11	
12	/**
13	 * Term price for an email plan, in ONE place shared by the split pre-check
14	 * (`orderEmailHosting`), the authoritative debit (`orderEmailHostingCore`) and
15	 * the PayPal/Coinbase order-creation actions. `emailMonthlyBaseCents` is the
16	 * plan's monthly base (seeded plans are monthly, so it is just `priceCents`).
17	 */
18	export async function emailChargeCents(
19	  plan: Parameters<typeof emailMonthlyBaseCents>[0],
20	  term: number,
21	): Promise<{ annualPct: number; fullCharge: number }> {
22	  const annualPct = await annualDiscountPct();
23	  const fullCharge = termPriceCents(emailMonthlyBaseCents(plan), term, annualPct);
24	  return { annualPct, fullCharge };
25	}
