1	/**
2	 * Pricing + renewal-period math for the recurring add-on products
3	 * (business email subscriptions and block-storage volumes).
4	 *
5	 * Deliberately PURE: no `db`, no I/O, no side effects — everything here is a
6	 * plain function over plain values so the renewal policy can be unit-tested
7	 * without a database. The worker sweep (`worker/product-renewals.ts`) owns all
8	 * the reads/writes and asks this module *what* should happen.
9	 *
10	 * Policy shape mirrors `worker/billing.ts` (VPS/domains) so customers see one
11	 * consistent billing behaviour across every product:
12	 *   warn before expiry -> expire -> grace period -> enforce (suspend / detach)
13	 */
14	
15	import { addMonths, termPriceCents } from "./billing-terms";
16	import { extraDiskCentsAt } from "./extra-disk";
17	
18	export const DAY_MS = 86_400_000;
19	
20	/** Read a positive integer from the environment, falling back on a default. */
21	export function envInt(name: string, fallback: number): number {
22	  const raw = process.env[name];
23	  const n = Number(raw);
24	  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
25	}
26	
27	/**
28	 * Days after expiry during which the product keeps working while we retry the
29	 * charge and nag the customer. Shares NXEON_GRACE_DAYS with worker/billing.ts
30	 * so every product on the account expires on the same schedule.
31	 */
32	export const PRODUCT_GRACE_DAYS = envInt("NXEON_GRACE_DAYS", 3);
33	
34	/** How many days before expiry we send the "renews soon" heads-up. */
35	export const PRODUCT_WARN_DAYS = envInt("NXEON_PRODUCT_WARN_DAYS", 3);
36	
37	/**
38	 * Days after the grace window before an unpaid, detached volume is considered
39	 * abandoned and may be reclaimed by staff. Nothing in this codebase deletes
40	 * customer data automatically — this only drives the wording of the warning so
41	 * the customer knows the disk will not sit there unpaid forever.
42	 */
43	export const PRODUCT_RECLAIM_DAYS = envInt("NXEON_TERMINATE_DAYS", 10);
44	
45	/** Notification dedupe window (matches the 4-day window used by billing.ts). */
46	export const NOTIFY_DEDUPE_DAYS = envInt("NXEON_PRODUCT_NOTIFY_DEDUPE_DAYS", 4);
47	
48	/** Volumes are priced per month and always renew monthly. */
49	export const VOLUME_TERM_MONTHS = 1;
50	
51	/** "$12.34" — the money format used across notifications and wallet lines. */
52	export function money(cents: number): string {
53	  return `$${(cents / 100).toFixed(2)}`;
54	}
55	
56	/** Date as "YYYY-MM-DD" for human-readable deadlines in notifications. */
57	export function ymd(d: Date): string {
58	  return d.toISOString().slice(0, 10);
59	}
60	
61	/** Amount charged to renew an email subscription for one plan term. */
62	export function emailRenewalCents(plan: { priceCents: number }): number {
63	  return Math.max(0, Math.round(plan.priceCents));
64	}
65	
66	/** Plan term in whole months, clamped to >= 1 so a bad row can't stall renewal. */
67	export function emailRenewalMonths(plan: { termMonths?: number | null }): number {
68	  const m = Math.round(Number(plan.termMonths ?? 1));
69	  return Number.isFinite(m) && m >= 1 ? m : 1;
70	}
71	
72	/**
73	 * The billing term (whole months) a subscription/account was SOLD on, clamped
74	 * to >= 1 so a bad row can never stall its renewal. This is the CUSTOMER'S chosen
75	 * term (1 = monthly, 12 = annual), stored on the subscription/account row — not
76	 * the plan's period. A pre-existing row (no column) defaults to 1 = monthly.
77	 */
78	export function subscriptionTermMonths(row: { termMonths?: number | null }): number {
79	  const m = Math.round(Number(row.termMonths ?? 1));
80	  return Number.isFinite(m) && m >= 1 ? m : 1;
81	}
82	
83	/**
84	 * The MONTHLY base price of an email plan. Every seeded email plan is priced
85	 * monthly (`termMonths: 1`), so this is normally just `priceCents`; dividing by the
86	 * plan's own term keeps it correct if an admin ever configures a multi-month plan.
87	 * The per-term charge is then `termPriceCents(base, subscriptionTerm, annualPct)`.
88	 */
89	export function emailMonthlyBaseCents(plan: { priceCents: number; termMonths?: number | null }): number {
90	  return Math.max(0, Math.round(plan.priceCents / emailRenewalMonths(plan)));
91	}
92	
93	/**
94	 * The annual discount FROZEN on an add-on row (HostingAccount / EmailSubscription)
95	 * at sale, or null when the row predates the column / was sold monthly. Mirrors
96	 * `frozenAnnualDiscountPct` in lib/annual-discount.ts: the cast contains the
97	 * stale-client gap (the symlinked prod Prisma client's types predate these columns
98	 * until it is regenerated at deploy — identical at runtime then). A frozen 0 is
99	 * honoured (nullish, not falsy); only a genuinely absent value falls back to live.
100	 */
101	export function frozenProductAnnualPct(row: unknown): number | null {
102	  const v = (row as { annualDiscountPct?: number | null } | null | undefined)?.annualDiscountPct;
103	  return typeof v === "number" && Number.isFinite(v) ? v : null;
104	}
105	
106	/**
107	 * What one renewal costs for a term-billed add-on product (Shared Hosting or
108	 * Business Email): `monthlyCents × months × (1 − annualDiscount)` — the SAME
109	 * formula VPS/game/NxCloud use (`termPriceCents`). `annualDiscountPct` is the rate
110	 * FROZEN on the row at sale, falling back to the live setting (passed by the sweep)
111	 * when the row predates the column or was sold monthly. So an annual account renews
112	 * annually at the rate it was sold — displayed === charged === renewed. For a
113	 * monthly term this is exactly the monthly price, so no existing row moves.
114	 */
115	export function productTermRenewalCents(
116	  monthlyCents: number,
117	  months: number,
118	  annualDiscountPct: number,
119	): number {
120	  return Math.max(0, termPriceCents(monthlyCents, months, annualDiscountPct));
121	}
122	
123	/**
124	 * Per-term renewal price of a hosting account (frozen annual rate wins). Adds any
125	 * purchased extra storage — billed every cycle at the current $/GB/mo, same as the
126	 * VPS add-on — so a customer who bought storage keeps paying for it each renewal.
127	 *
128	 * THE renewal-price formula for shared hosting: worker/product-renewals.ts's
129	 * `chargeHostingRenewal` charges exactly this, so anywhere that DISPLAYS a
130	 * hosting renewal amount (lib/nx/services.ts's "My Services" list) must call
131	 * this too rather than re-deriving it — a second copy of this formula is how
132	 * `plan.priceCents` (the raw monthly list price, ignoring the annual discount
133	 * and extra disk) ended up on a customer-facing screen before.
134	 */
135	export function hostingRenewalPrice(
136	  acct: { termMonths?: number | null; annualDiscountPct?: number | null; extraDiskGB?: number | null; plan: { priceCents: number } },
137	  liveAnnual: number,
138	  perGbCents: number,
139	): number {
140	  const months = subscriptionTermMonths(acct);
141	  const annual = frozenProductAnnualPct(acct) ?? liveAnnual;
142	  return productTermRenewalCents(acct.plan.priceCents, months, annual) + extraDiskCentsAt(acct.extraDiskGB ?? 0, perGbCents) * months;
143	}
144	
145	/** Amount charged to renew a volume for one month. */
146	export function volumeRenewalCents(volume: { priceCents: number }): number {
147	  return Math.max(0, Math.round(volume.priceCents));
148	}
149	
150	/**
151	 * The expiry a renewal should advance to.
152	 *
153	 * The base is `max(currentExpiry, now)`, so an item that has been expired for
154	 * months is brought forward to one full term from *today* with a single charge
155	 * rather than being back-billed for every missed period. This also guarantees
156	 * the new expiry is always strictly in the future, which is what makes the
157	 * sweep idempotent (the "due" query only selects `expiresAt < now`).
158	 */
159	export function nextExpiry(
160	  currentExpiry: Date | null | undefined,
161	  now: Date,
162	  months: number
163	): Date {
164	  const base = new Date(
165	    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
166	  );
167	  return addMonths(base, Math.max(1, Math.round(months)));
168	}
169	
170	/** Instant the grace period ends for an item that expired at `expiresAt`. */
171	export function graceEndsAt(expiresAt: Date, graceDays: number = PRODUCT_GRACE_DAYS): Date {
172	  return new Date(expiresAt.getTime() + graceDays * DAY_MS);
173	}
174	
175	/** True once the grace period after `expiresAt` has fully elapsed. */
176	export function isPastGrace(
177	  expiresAt: Date,
178	  now: Date,
179	  graceDays: number = PRODUCT_GRACE_DAYS
180	): boolean {
181	  return now.getTime() > graceEndsAt(expiresAt, graceDays).getTime();
182	}
183	
184	/** Date after which an unpaid volume may be reclaimed (messaging only). */
185	export function reclaimAt(
186	  expiresAt: Date,
187	  graceDays: number = PRODUCT_GRACE_DAYS,
188	  reclaimDays: number = PRODUCT_RECLAIM_DAYS
189	): Date {
190	  return new Date(expiresAt.getTime() + (graceDays + reclaimDays) * DAY_MS);
191	}
192	
193	/** Lower bound for "have we already sent this notification recently?" lookups. */
194	export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
195	  return new Date(now.getTime() - days * DAY_MS);
196	}
197	
198	/** True when the item has passed its paid-through date and owes a renewal. */
199	export function isDueForRenewal(expiresAt: Date | null | undefined, now: Date): boolean {
200	  return !!expiresAt && expiresAt.getTime() < now.getTime();
201	}
202	
203	/** True when the item expires inside the pre-expiry warning window. */
204	export function isRenewingSoon(
205	  expiresAt: Date | null | undefined,
206	  now: Date,
207	  warnDays: number = PRODUCT_WARN_DAYS
208	): boolean {
209	  if (!expiresAt) return false;
210	  const t = expiresAt.getTime();
211	  return t > now.getTime() && t < now.getTime() + warnDays * DAY_MS;
212	}
213	
214	/** Whether the wallet covers a renewal (free items always "afford" themselves). */
215	export function canAfford(balanceCents: number, priceCents: number): boolean {
216	  return priceCents <= 0 || balanceCents >= priceCents;
217	}
218	
219	/**
220	 * What the sweep should do with an item that is past its expiry date.
221	 *  - `renew`   charge the wallet and push `expiresAt` forward
222	 *  - `grace`   still inside the grace window: leave it running, nag the owner
223	 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
224	 */
225	export type RenewalAction = "renew" | "grace" | "enforce";
226	
227	export function renewalDecision(opts: {
228	  expiresAt: Date;
229	  now: Date;
230	  autoRenew: boolean;
231	  balanceCents: number;
232	  priceCents: number;
233	  graceDays?: number;
234	}): RenewalAction {
235	  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
236	  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
237	  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
238	  return "grace";
239	}
240	
241	/**
242	 * Whether a pre-expiry warning is warranted: only bother the customer when the
243	 * renewal would actually fail today (auto-renew off, or wallet too low).
244	 */
245	export function needsUpcomingWarning(opts: {
246	  autoRenew: boolean;
247	  balanceCents: number;
248	  priceCents: number;
249	}): boolean {
250	  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
251	}
