404	test("what Add storage shows is what diskExpandQuote charges, over every term", async () => {
405	  const { extraDiskProrateCents } = await import("../lib/extra-disk.ts");
406	  const { remainingMonths } = await import("../lib/proration.ts");
407	  const now = Date.parse("2026-07-27T00:00:00.000Z");
408	  // Real purchasable amounts at the live $0.10/GB/mo, across every VPS term plus a
409	  // stacked "Renew now" window and a term with hours left on it.
410	  for (const gb of [10, 50, 100, 250, 500]) {
411	    for (const months of [0.002, 1, 12, 24, 36, 72]) {
412	      const monthlyCents = extraDiskCentsAt(gb, 10);
413	      const expiresAt = now + months * 30.44 * 86400_000;
414	      const charged = extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), now));
415	      // The component calls these very functions with these very arguments, so
416	      // "shown" and "charged" are now the same expression by construction rather
417	      // than by two copies agreeing.
418	      assert.equal(charged, extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), now)));
419	      assert.ok(Number.isInteger(charged) && charged >= 0, `${gb} GB over ${months} months produced ${charged}`);
420	    }
421	  }
422	  // An expired term prorates to nothing rather than crediting the customer.
423	  assert.equal(extraDiskProrateCents(500, remainingMonths(new Date(now - 86400_000), now)), 0);
424	  // 50 GB at 10c/GB/mo for a full year is the figure a customer actually sees.
425	  assert.equal(extraDiskProrateCents(extraDiskCentsAt(50, 10), 12), 6000);
